<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle??$themeName) ?></title><link rel="stylesheet" href="<?= e(site_url('themes/newspress/assets/style.css')) ?>"></head><body><div class="top">THE DAILY EDITION <span><?= date('l, F j, Y') ?></span></div><header class="wrap masthead"><a href="<?= e(site_url()) ?>">PAPER CAST</a><small>NEWS · CULTURE · IDEAS</small></header><nav><div class="wrap"><a href="<?= e(site_url()) ?>">HOME</a><a href="<?= e(site_url('about.php')) ?>">ABOUT</a><form action="<?= e(site_url('search.php')) ?>"><input name="q" placeholder="Search stories"><button>⌕</button></form></div></nav><main class="wrap layout"><section><h2 class="section-title">LATEST STORIES</h2><div class="stories"><?php foreach($posts as $post): ?><article><?php if($post['cover_image']): ?><img src="<?= e($post['cover_image']) ?>" alt=""><?php endif ?><small><?= e($post['category_name']??'NEWS') ?></small><h2><a href="<?= e(site_url('article.php?slug='.rawurlencode($post['slug']))) ?>"><?= e($post['title']) ?></a></h2><p><?= e($post['excerpt']??'') ?></p></article><?php endforeach ?><?php if(!$posts): ?><p>No stories published yet.</p><?php endif ?></div></section><aside><h3>ABOUT PAPER CAST</h3><p>An independent space for stories, culture, and ideas.</p><h3>POPULAR TOPICS</h3><p>News · Culture · Technology · Lifestyle</p></aside></main></body></html>
